import{_ as l,l as i,o as e,c as r,v as o,p as n,x as s,d,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const g=JSON.parse('{"title":"剂量-焦深耦合","description":"","frontmatter":{"title":"剂量-焦深耦合","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/dose-focus-coupling.md","filePath":"litho/dose-focus-coupling.md","lastUpdated":1789023840000}'),u={name:"litho/dose-focus-coupling.md"};function E(c,a,m,B,_,f){const t=i("Mermaid");return e(),r("div",null,[a[1]||(a[1]=o('<h1 id="剂量-焦深耦合" tabindex="-1">剂量-焦深耦合 <a class="header-anchor" href="#剂量-焦深耦合" aria-label="Permalink to &quot;剂量-焦深耦合&quot;">​</a></h1><div class="epigraph"><p>剂量轴上的 $\\mathrm{CD}(E)$ 与焦轴上的 Bossung 不是两次独立实验：离焦掉 NILS，同一相对剂量误差会走出更大的 CD，窗在两个方向同时收。</p><footer>—— 据 Mack 对 E–D 窗口与 Bossung；胶核如何改弯曲的讨论整理</footer></div><p><a href="/litho/dose-to-size">上一课</a>在最佳焦附近画出 \\(\\mathrm{CD}(E)\\)。<a href="/litho/bossung-curve">Bossung 曲线</a>与 <a href="/litho/ed-process-window">E–D 窗口</a>在主干已经把两轴画在一起。缺口是胶这一侧：反应–扩散与显影如何让剂量与焦深耦，而不是再推一次 \\(\\lambda/\\mathrm{NA}^2\\)。本课钉耦合。显影后热流另起炉灶，留给<a href="/litho/resist-reflow">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>光学上，离焦使空中像调制变浅，阈值处 ILS 下降。剂量一漂，边走得更远——所以 Bossung 族在离焦端散开。胶的 \\(\\gamma\\) 高、\\(\\ell\\) 大，都是在已经变浅的潜像上再乘一道：有效 NILS 更低，同样的离焦走出更弯的 CD。耦合因此是乘法，不是「先光学后胶各报各的窗再取最小」。</p><p>缺口不是重画 E–D 面积，而是：改 PEB、改淬灭、改胶厚，Bossung 弯曲会变，即使镜头没动。把焦深规格写成纯光学 \\(k_2\\)，会把轨道超差判成扫描机失焦。</p><h3 id="等焦剂量会被胶搬走" tabindex="-1">等焦剂量会被胶搬走 <a class="header-anchor" href="#等焦剂量会被胶搬走" aria-label="Permalink to &quot;等焦剂量会被胶搬走&quot;">​</a></h3><p>主干 Bossung 课指出等焦附近 CD 对 \\(z\\) 不敏感。化学阈值切点随 \\(E_0\\)、负载、\\(\\gamma\\) 移动时，等焦对应的剂量跟着走。密线与孤立线的等焦差，一部分来自光学 OPE，一部分来自胶核对不同空间频率的衰减不同。RET 换照明改前一项；换 PEB 改后一项。</p><p><span class="marginnote">不要在本课重导瑞利焦深公式。尺度仍是 \\(\\propto\\lambda/\\mathrm{NA}^2\\)；本课只问胶如何改「还活着的那块面积」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>实验：完整曝光–散焦矩阵，而不是只扫剂量或只扫焦。比较「只改 PEB」与「只改照明」两张 Bossung：前者弯曲形态变、最佳焦可能微移（轴向吸收与剖面）；后者调制结构变。模拟：同一 TCC，换胶核，应能复现弯曲差——这是 LPM / 轮廓仿真的签核，不是光学课的签核。</p><p>High-NA 胶厚与 DOF 已经挤在同一预算里，见<a href="/litho/high-na-resist-budget">胶厚预算</a>。耦合在薄膜上更狠：膜顶膜底不在同一焦面，剂量清底与焦面选择绑死。</p>',12)),(e(),n(p,null,{default:s(()=>[h(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEF%5B%22%E7%A6%BB%E7%84%A6%20%E2%86%92%20NILS%20%E4%B8%8B%E9%99%8D%22%5D%20--%3E%20COUP%5B%22%E6%9C%89%E6%95%88%E6%96%9C%E7%8E%87%22%5D%0A%20%20GAMMA%5B%22%CE%B3%20%E4%B8%8E%20%E2%84%93%22%5D%20--%3E%20COUP%0A%20%20COUP%20--%3E%20BOSS%5B%22Bossung%20%E5%BC%AF%E6%9B%B2%22%5D%0A%20%20E%5B%22%E5%89%82%E9%87%8F%22%5D%20--%3E%20BOSS%0A%20%20BOSS%20--%3E%20ED%5B%22E-D%20%E9%9D%A2%E7%A7%AF%22%5D%0A"})]),fallback:s(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=o('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>潜像强度可看成空中像经化学核卷积。离焦改空中像，核改卷积后的边。剂量改切在卷积后剖线的哪一条等高线。三条一起决定 CD。核越宽，离焦造成的对比损失越被「已经很糊」掩盖，有时弯曲看起来变平——那不是焦深变好，是分辨率已经交出去，等焦假象。Mack 警告过：平的 Bossung 不等于高 NILS。</p><p>吸收沿 \\(z\\) 不均匀时，最佳焦随剂量走（dose-focus 倾斜）：过剂量更吃底部或顶部，视漂白与衰减方向而定。Dill \\(A\\)、\\(B\\) 在这里进入焦轴，薄膜课的 \\(I(z)\\) 变成 Bossung 的不对称。</p><p><span class="marginnote">矢量成像改 \\(I\\) 本身，耦合定义不变。偏振课不在这里重开。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不把某代机台的焦深验收表写进胶规格。随机缺陷会在平均 E–D 窗内部先切一刀，那是后一单元的随机工艺窗口。下一课热回流发生在显影之后，不改曝光时的剂量–焦耦合，但会改最终 CD 对烘箱的敏感，看起来像「又一条焦轴」——物理是黏度，不要并进本课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>离焦掉 ILS，胶的 \\(\\gamma\\) 与 \\(\\ell\\) 再乘，Bossung 弯曲是耦合结果。</li><li>改 PEB / 淬灭 / 厚会改焦窗，即使镜头未动。</li><li>等焦剂量随化学切点走；平曲线可能是核过糊。</li><li>Dill 吸收造成剂量–最佳焦倾斜。</li><li>出处：Mack 对 Bossung 与 E–D；主干窗口课。</li></ul>',8))])}const A=l(u,[["render",E]]);export{g as __pageData,A as default};
